// D-32 gate templates: director and above only; scopes base / client / programme / country; a project takes the
// most specific; saving replaces (archives) the scope's template; archiving falls back. Generated by gen:command.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, countRows, createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  Forbidden,
  grantOf,
  openTestKernel,
  RuleViolation,
  ValidationFailed,
  type TestKernel,
} from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { archiveGateTemplate } from '../commands/archive-gate-template.ts';
import { recordStep } from '../commands/record-step.ts';
import { saveGateTemplate } from '../commands/save-gate-template.ts';
import { gateTemplates } from '../queries/gate-templates.ts';
import { siteLifecycle } from '../queries/site-lifecycle.ts';

const director = aStaffActor({ roles: ['director'] });
const pm = aStaffActor({ roles: ['pm'] });
let testDb: TestDatabase;
let t: TestKernel;
let client: string;
let siteES: string;
let siteDE: string;
const gates = (...names: string[]) => names.map((name, n) => ({ key: `g${String(n + 1)}`, name }));
const save = (input: Record<string, unknown>) => t.kernel.execute(saveGateTemplate, director, input, 'test');
const gateNames = async (siteId: string) =>
  (await t.kernel.read(siteLifecycle, pm, { siteId })).gates.map((g) => g.name);

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url);
  t.grant(
    director,
    createClient.permission,
    createSite.permission,
    saveGateTemplate.permission,
    archiveGateTemplate.permission,
    gateTemplates.permission,
  );
  t.grant(pm, siteLifecycle.permission, recordStep.permission);
  ({ id: client } = await t.kernel.execute(
    createClient,
    director,
    { shortCode: 'CLIENTA', name: 'Client A' },
    'test',
  ));
  const place = { cityCode: 'XXX', cityName: 'City', name: 'Store', standard: 'S' };
  ({ id: siteES } = await t.kernel.execute(
    createSite,
    director,
    { clientId: client, countryCode: 'ES', ...place },
    'test',
  ));
  ({ id: siteDE } = await t.kernel.execute(
    createSite,
    director,
    { clientId: client, countryCode: 'DE', ...place },
    'test',
  ));
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('D-32 gate templates', () => {
  it('only directors and sponsors change templates; a PM cannot', async () => {
    expect(grantOf(saveGateTemplate.permission)?.roles).toEqual(['director', 'sponsor']);
    await expect(
      t.kernel.execute(saveGateTemplate, pm, { clientId: null, name: 'Base', gates: gates('Go') }, 'test'),
    ).rejects.toBeInstanceOf(Forbidden);
  });

  it('refuses duplicate keys, a base step name, and a programme without its client', async () => {
    await expect(
      save({
        clientId: null,
        name: 'X',
        gates: [
          { key: 'g1', name: 'a' },
          { key: 'g1', name: 'b' },
        ],
      }),
    ).rejects.toBeInstanceOf(ValidationFailed);
    await expect(
      save({ clientId: null, name: 'X', gates: [{ key: 'installed', name: 'a' }] }),
    ).rejects.toBeInstanceOf(ValidationFailed);
    await expect(
      save({ clientId: null, programmeId: randomUUID(), name: 'X', gates: gates('a') }),
    ).rejects.toBeInstanceOf(ValidationFailed);
  });

  it('a project takes the most specific template: base, then client, then client + country', async () => {
    await save({ clientId: null, name: 'Base', gates: gates('Kick-off', 'Handover') });
    expect(await gateNames(siteES)).toEqual(['Kick-off', 'Handover']);
    await save({ clientId: client, name: 'Client A', gates: gates('Go/no-go', 'Compliance', 'Go-live') });
    await save({
      clientId: client,
      countryCode: 'ES',
      name: 'Client A ES',
      gates: gates('Go/no-go', 'Permits ES', 'Go-live'),
    });
    expect(await gateNames(siteES)).toEqual(['Go/no-go', 'Permits ES', 'Go-live']);
    expect(await gateNames(siteDE)).toEqual(['Go/no-go', 'Compliance', 'Go-live']);
  });

  it('saving again replaces the scope (old archived); archiving falls back; recorded steps stay', async () => {
    await t.kernel.execute(recordStep, pm, { siteId: siteES, step: 'g2', doneOn: '2026-11-14' }, 'test');
    const r = await save({
      clientId: client,
      countryCode: 'ES',
      name: 'Client A ES v2',
      gates: gates('Go/no-go', 'Permits ES v2'),
    });
    expect(r.replaced).not.toBeNull();
    expect(
      await countRows(testDb.url, `gate_template WHERE country_code = 'ES' AND archived_at IS NOT NULL`),
    ).toBe(1);
    expect(await gateNames(siteES)).toEqual(['Go/no-go', 'Permits ES v2']);
    await t.kernel.execute(archiveGateTemplate, director, { id: r.id }, 'test');
    expect(await gateNames(siteES)).toEqual(['Go/no-go', 'Compliance', 'Go-live']);
    expect(
      await countRows(testDb.url, `site_step WHERE site_id = $1 AND step = 'g2' AND archived_at IS NULL`, [
        siteES,
      ]),
    ).toBe(1);
    expect((await t.kernel.read(gateTemplates, director, {})).map((x) => x.name)).toEqual([
      'Base',
      'Client A',
    ]);
  });

  it('a gate the project template does not have is refused', async () => {
    await expect(
      t.kernel.execute(recordStep, pm, { siteId: siteDE, step: 'g9', doneOn: '2026-11-14' }, 'test'),
    ).rejects.toBeInstanceOf(RuleViolation);
  });
});
